function liveHTML(){const trs=triggers();const ups=trs.filter(t=>t.kind==="up"),dns=trs.filter(t=>t.kind==="down");const up$=ups.reduce((a,t)=>a+t.annualCost,0),dn$=dns.reduce((a,t)=>a-t.annualCost,0);const st=stepOf(T.step)||STEPS[0];
 const cards=trs.map(t=>{const made=T.made[t.id];const head=t.alloc-t.used-Math.max(0,t.annualCost);const e=t.e;return `<div class="tb-tg ${t.kind}"><div class="row sp" style="flex-wrap:wrap"><span class="pill ${t.kind==="up"?(t.inWeeks<=t.e.st.lead?"bad":"warn"):"good"}">${t.kind==="up"?(t.inWeeks===0?"Needed now":"In "+t.inWeeks+" week"+(t.inWeeks===1?"":"s")):"Scale down"}</span><b>${H(t.serviceName)}</b><span class="num" data-role="metric">${t.annualCost>=0?"+":"-"}${D$(Math.abs(t.annualCost))} a year</span></div><p class="small" style="margin:6px 0">${H(t.text)}</p><p class="small muted" style="margin:0 0 8px">Funding: ${H(t.fund)}. Allocated ${D$(t.alloc)}, committed ${D$(t.used)}${t.kind==="up"?`, so ${head>=0?`<b>${D$(head)} of headroom remains</b>`:`<b class="tb-bad">${D$(-head)} short: needs a budget transfer</b>`}`:`. Retiring frees ${D$(-t.annualCost)}.`}</p><div class="row" style="flex-wrap:wrap"><button class="btn ${made?"quiet":"primary"}" data-tbm-demand="${t.id}" ${made?"disabled":""}>${made?"Demand "+made+" created":t.kind==="up"?"Create demand":"Create decommission demand"}</button><button class="btn quiet" data-tbm-step="${t.step}">Show the curve</button><button class="btn quiet" data-tbm-svc="${t.service}">Open service</button></div></div>`}).join("");
 return `${statrow([stat("Scale-up triggers",ups.length,"inside "+T.sc.weeks+" weeks",ups.length?"crit":""),stat("Added run cost",D$(up$),"a year if all are built"),stat("Scale-down savings",D$(dn$),"a year, "+dns.length+" candidates"),stat("Net change",(up$-dn$>=0?"+":"-")+D$(Math.abs(up$-dn$)),"a year"),stat("Soonest",ups.length?(ups[0].inWeeks===0?"now":ups[0].inWeeks+(ups[0].inWeeks===1?" week":" weeks")):"none",ups.length?H(ups[0].serviceName):"nothing crosses a line")])}<div class="tb-tgs">${cards||'<p class="muted">No capacity line is crossed in this horizon.</p>'}</div>
 <div class="grid g2" style="align-items:start;margin-top:14px">${card("Demand against capacity: "+H(st.name),"Purple is forecast demand. The red dashes are capacity today; the green dots are capacity after the triggered step.",timeline(st),`<select data-tbm-pick aria-label="Choose scaling step">${STEPS.map(s=>`<option value="${s.id}" ${s.id===T.step?"selected":""}>${H(s.name)}</option>`).join("")}</select>`)}${card("Stepped cost curve","Cost rises in steps, not smoothly: one more unit of demand can cost a whole analyst or node.",stepCurve(st),"")}</div>`}
